//                             Item Counter
//                       By Apollia Pirandello
//                              9/19/2007
//
// Public domain.  Free to use and/or modify for any purpose,
// including commercial purposes.
//
// Once you drop this script in any prim, it will immediately
// tell you in an OwnerSay how many items are in that prim,
// minus 1, so the script itself isn't counted.
//
// It will also do that whenever the prim is touched.
//**********SCRIPT BEGINS BELOW**********
//****VARIABLE
integer
items_contained
;
//****END OF VARIABLE SECTION
//****FUNCTIONS****
CountItems
()
{
items_contained
=
llGetInventoryNumber
(
INVENTORY_ALL
);
--
items_contained
;
//minus 1, the script itself isn't counted, since its used with the INVENTORY_ALL flag
}
SayCount
()
{
llOwnerSay
(
"This prim contains "
+
(
string
)
items_contained
+
" items."
);
}
//****END OF FUNCTIONS****
//****DEFAULT STATE****
default
{
state_entry
()
{
CountItems
();
SayCount
();
}
touch_start
(
integer
total_number
)
{
CountItems
();
SayCount
();
}
}
